package com.hbm.machine.reactor.pile.core;
import com.hbm.api.tool.ToolableBlock;import com.hbm.registry.HbmSounds;import com.mojang.serialization.MapCodec;import java.util.List;import net.minecraft.core.*;import net.minecraft.sounds.SoundSource;import net.minecraft.util.Mth;import net.minecraft.world.*;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.material.MapColor;import net.minecraft.world.level.storage.loot.LootParams;import net.minecraft.world.phys.BlockHitResult;import net.minecraft.world.phys.shapes.*;
public final class PileDeviceBlock extends BaseEntityBlock implements ToolableBlock {
 public PileDeviceBlock(){super(Properties.of().mapColor(MapColor.METAL).strength(5,6).sound(SoundType.METAL).requiresCorrectToolForDrops().noOcclusion().isRedstoneConductor((state,level,pos)->false).isSuffocating((state,level,pos)->false).isViewBlocking((state,level,pos)->false));registerDefaultState(stateDefinition.any().setValue(PileCoreContent.META,0));}
 @Override protected MapCodec<? extends BaseEntityBlock> codec(){return MapCodec.unit(this);}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState> builder){builder.add(PileCoreContent.META);}@Override protected RenderShape getRenderShape(BlockState state){return RenderShape.INVISIBLE;}
 @Override protected int getLightBlock(BlockState state,BlockGetter level,BlockPos pos){return 0;}@Override protected boolean propagatesSkylightDown(BlockState state,BlockGetter level,BlockPos pos){return true;}
 @Override public BlockState getStateForPlacement(BlockPlaceContext context){int item=PileDeviceItem.metadata(context.getItemInHand()),base=item>=2?8:item==1?4:0;return defaultBlockState().setValue(PileCoreContent.META,base+Mth.clamp(context.getClickedFace().ordinal()-2,0,3));}
 @Override public void setPlacedBy(Level level,BlockPos pos,BlockState state,LivingEntity entity,ItemStack stack){if(state.getValue(PileCoreContent.META)==8){int quadrant=Mth.floor(entity.getYRot()*4F/360F+.5)&3;level.setBlock(pos,state.setValue(PileCoreContent.META,8+new int[]{0,3,1,2}[quadrant]),2);}}
 @Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return switch(state.getValue(PileCoreContent.META)/4){case 0->new TileEntityPileLoader(pos,state);case 1->new TileEntityPileVent(pos,state);default->new TileEntityPileControl(pos,state);};}
 @Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level,BlockState state,BlockEntityType<T> type){return switch(state.getValue(PileCoreContent.META)/4){case 0->createTickerHelper(type,PileCoreContent.LOADER.get(),PileTickingBlockEntity::tick);case 1->createTickerHelper(type,PileCoreContent.VENT.get(),PileTickingBlockEntity::tick);default->createTickerHelper(type,PileCoreContent.CONTROL.get(),PileTickingBlockEntity::tick);};}
 @Override protected List<ItemStack> getDrops(BlockState state,LootParams.Builder context){return List.of(PileCoreContent.DEVICE_ITEM.get().stack(state.getValue(PileCoreContent.META)/4));}
 @Override public ItemStack getCloneItemStack(BlockState state,net.minecraft.world.phys.HitResult hit,LevelReader level,BlockPos pos,Player player){return PileCoreContent.DEVICE_ITEM.get().stack(state.getValue(PileCoreContent.META)/4);}
 @Override protected InteractionResult useWithoutItem(BlockState state,Level level,BlockPos pos,Player player,BlockHitResult hit){return activate(state,level,pos,player,InteractionHand.MAIN_HAND);}
 @Override protected ItemInteractionResult useItemOn(ItemStack stack,BlockState state,Level level,BlockPos pos,Player player,InteractionHand hand,BlockHitResult hit){var result=activate(state,level,pos,player,hand);return result.consumesAction()?ItemInteractionResult.sidedSuccess(level.isClientSide):ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;}
 private InteractionResult activate(BlockState state,Level level,BlockPos pos,Player player,InteractionHand hand){if(player.isShiftKeyDown()||state.getValue(PileCoreContent.META)/4!=0)return InteractionResult.PASS;if(level.isClientSide)return InteractionResult.SUCCESS;if(level.getBlockEntity(pos) instanceof TileEntityPileLoader loader&&loader.level<=0&&!loader.loading){var held=player.getItemInHand(hand);if(loader.stack==null&&TileEntityPileLoader.isItemLoadable(held)){loader.stack=held.copyWithCount(1);held.shrink(1);level.playSound(null,pos,HbmSounds.get("item.upgradePlug"),SoundSource.BLOCKS,1,1);loader.setChanged();return InteractionResult.CONSUME;}loader.loading=true;loader.setChanged();}return InteractionResult.CONSUME;}
 @Override protected VoxelShape getBlockSupportShape(BlockState state,BlockGetter level,BlockPos pos){int meta=state.getValue(PileCoreContent.META);if(meta>=4&&meta<8)return Shapes.empty();return switch(meta%4){case 0->Block.box(0,0,0,16,16,1);case 1->Block.box(0,0,15,16,16,16);case 2->Block.box(0,0,0,1,16,16);default->Block.box(15,0,0,16,16,16);};}
 @Override public boolean onScrew(Level level,Player player,BlockPos pos,Direction side,float hx,float hy,float hz,ToolType tool){int meta=level.getBlockState(pos).getValue(PileCoreContent.META);if(meta>=8){pos=pos.below();side=Direction.UP;}else{side=Direction.values()[meta%4+2];pos=pos.relative(side.getOpposite());}return level.getBlockState(pos).getBlock() instanceof PileBodyBlock body&&body.onScrew(level,player,pos,side,hx,hy,hz,tool);}
}
